(args, got) => {
      const [orig, key] = args;
      const want = orig.filter(v => v !== null && v !== key).sort((a, b) => a - b);
      if (!Array.isArray(got)) return false;
      if (got.filter(v => v !== null).length !== want.length) return false;
      if (!got.length) return want.length === 0;
      if (got[0] === null) return false;
      const mk = v => ({ v, l: null, r: null });
      const root = mk(got[0]), q = [root];
      let i = 1, qi = 0;
      while (qi < q.length && i < got.length) {
        const n = q[qi++];
        if (i < got.length && got[i] !== null) { n.l = mk(got[i]); q.push(n.l); } i++;
        if (i < got.length && got[i] !== null) { n.r = mk(got[i]); q.push(n.r); } i++;
      }
      if (q.length !== want.length) return false;
      const out = [], st = [];
      let cur = root;
      while (cur || st.length) {
        while (cur) { st.push(cur); cur = cur.l; }
        cur = st.pop(); out.push(cur.v); cur = cur.r;
      }
      return out.length === want.length && out.every((v, j) => v === want[j]);
    }

