function removeKey(root: TreeNode | null, key: number): TreeNode | null {
  let parent: TreeNode | null = null, cur = root;
  while (cur && cur.val !== key) { parent = cur; cur = key < cur.val ? cur.left : cur.right; }
  if (!cur) return root;
  let repl: TreeNode | null;
  if (!cur.left) repl = cur.right;
  else if (!cur.right) repl = cur.left;
  else {
    let m = cur.right;
    while (m.left) m = m.left;
    m.left = cur.left;
    repl = cur.right;
  }
  if (!parent) return repl;
  if (parent.left === cur) parent.left = repl; else parent.right = repl;
  return root;
}

