function removeKey(root: TreeNode | null, key: number): TreeNode | null {
  if (!root) return null;
  if (key < root.val) { root.left = removeKey(root.left, key); return root; }
  if (key > root.val) { root.right = removeKey(root.right, key); return root; }
  if (!root.left) return root.right;
  if (!root.right) return root.left;
  let s = root.right;
  while (s.left) s = s.left;
  root.val = s.val;
  root.right = removeKey(root.right, s.val);
  return root;
}

